// UTF-8로 저장될 때의 바이트 수를 코드 포인트 범위로 직접 센다 (RFC 3629 표와 같은 규칙)
function utf8Bytes(s: string): number {
  let n = 0;
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    n += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  }
  return n;
}

// 1) 32비트 정수 칸에 2147483647 + 1을 저장
const next = 2147483647 + 1;       // number 연산: 64비트 부동소수점이라 범위가 충분하다
const ids = new Int32Array([2147483647]);
ids[0] = next;                     // 32비트 정수 칸에 저장
console.log(ids[0]);
console.log(next);

// 2) 길이를 세 가지로 센다: [JS length, 코드 포인트 수, UTF-8 바이트 수]
const name = "김서연디자이너팀장님";
console.log(name.length, [...name].length, utf8Bytes(name));
const e = "e\u0301";
console.log(e.length, [...e].length, utf8Bytes(e));
const emoji = "😀";
console.log(emoji.length, [...emoji].length, utf8Bytes(emoji));

